462	function fileDigest(root, path) {
463	  const absolute = resolve(root, path);
464	  const within = relative(root, absolute);
465	  if (within === ".." || within.startsWith(`..${sep}`) || isAbsolute(within))
466	    throw new Error("reference escapes root");
467	  let current = root;
468	  for (const segment of path.split("/")) {
469	    current = resolve(current, segment);
470	    if (!existsSync(current)) return null;
471	    const stat = lstatSync(current);
472	    if (stat.isSymbolicLink()) throw new Error("reference traverses symlink");
473	  }
474	  if (!lstatSync(absolute).isFile()) throw new Error("reference is not a regular file");
475	  return createHash("sha256").update(readFileSync(absolute)).digest("hex");
