481	  const paths = [];
482	  for (let index = 0; index < entries.length; index += 1) {
483	    const entry = entries[index];
484	    if (!entry) continue;
485	    const status = entry.slice(0, 2);
486	    const path = entry.slice(3);
487	    if (status.includes("R") || status.includes("C")) index += 1;
488	    if (path === stateRelative || path === `${stateRelative}.lock`) continue;
489	    paths.push({ path, sha256: fileDigest(root, path) ?? "deleted" });
